# --- Your fetch function ---
def fetch_news(stock_id, page=0, size=10):
    """Fetch one page of news for a given stock ID."""
    url = f"https://groww.in/v1/api/groww-news/v2/stocks/news/{stock_id}?page={page}&size={size}"
    try:
        resp = requests.get(url, headers={"User-Agent": "Mozilla/5.0"}, timeout=20)
        if resp.status_code == 200:
            return stock_id, resp.json().get("results", [])
        else:
            #print(f"Failed for {stock_id}: {resp.status_code}")
            failed_responses.append(stock_id)
            return stock_id, []
    except requests.exceptions.SSLError as e:
        print(f"SSL error for {stock_id}: {e}")
        return stock_id, []
    except requests.exceptions.ConnectionError as e:
        print(f"Connection error for {stock_id}: {e}")
        return stock_id, []
    except http.client.RemoteDisconnected as e:
        print(f"Remote disconnected for {stock_id}: {e}")
        return stock_id, []
    except Exception as e:
        print(f"Error for {stock_id}: {e}")
        return stock_id, []

# --- Batch helper ---
def chunks(lst, n):
    """Yield successive n-sized chunks from list."""
    for i in range(0, len(lst), n):
        yield lst[i:i + n]

# --- Main execution ---
batch_size = 50   # how many IDs per batch
max_workers = 20  # threads per batch
pause_between_batches = 5  # seconds

# 100 - 20 - 5 ==> 1088 seconds  taken 
# 200 - 20 - 5 ==> 743 seconds ; 593 failr
# 150 - 20 - 5 ==> 847 sec ; 0 failure
with open("stock_news.csv", "w", newline="", encoding="utf-8") as f:
    writer = csv.writer(f)
    headers = ["StockID", "NewsID", "Title", "Summary", "Source", "PubDate", "URL"]
    writer.writerow(headers)

    # Process in batches
    for batch_num, batch in enumerate(chunks(gstk_ids, batch_size), start=1):
        #print(f"\n🚀 Processing batch {batch_num} with {len(batch)} IDs...")
        with ThreadPoolExecutor(max_workers=max_workers) as executor:
            futures = [executor.submit(fetch_news, stock_id) for stock_id in batch]

            for future in as_completed(futures):
                stock_id, results = future.result()
                #if round(time.time() - start_time) % 10 == 0:
                #    print(".. Dont worry I'm still working..")
                for item in results:
                    writer.writerow([
                        stock_id,
                        item.get("id"),
                        item.get("title"),
                        item.get("summary"),
                        item.get("source"),
                        item.get("pubDate"),
                        item.get("url")
                    ])
        print(f"✅ {round(batch_num*100/(len(gstk_ids)/batch_size),2)} % Done | {len(failed_responses)} Failed | Finished batch {batch_num} out of {len(gstk_ids)/batch_size}, pausing {pause_between_batches}s...")
        time.sleep(pause_between_batches)


news_df = pd.read_csv('stock_news.csv')
mapping_df= pd.read_csv('stocks.csv')[['StockID','Company','NSE Code']]

final_df = pd.merge(mapping_df,news_df,how='left')
final_df.to_csv("stock_news_with_names.csv", index=False)
end_time = time.time()


print(f"\nExecution time: {end_time - start_time:.2f} seconds")
print("✅ News fetched in parallel and saved to stock_news.csv")
